// Type traits can check for noexcept move constructors.
// STL containers use similar checks to choose move vs. copy.

#include <utility> // for std::move
#include <type_traits> // for std::is_nothrow_move_constructible

struct CanThrowOnMove { // Missing noexcept
    CanThrowOnMove(CanThrowOnMove&& other) { /* ... */ } 
};

struct WontThrowOnMove { // Explicitly noexcept
    WontThrowOnMove(WontThrowOnMove&& other) noexcept { /* ... */ } 
};

